flask_restful.utils (OrderedDict) with faithful reference copies, then run
the real /workspace tests under pytest."""
import sys
import types
from collections import OrderedDict

pkg = types.ModuleType('flask_restful')
pkg.__path__ = ['/workspace/flask_restful']


def marshal(data, fields, envelope=None):
    # verbatim copy of the reference flask_restful.marshal
    def make(cls):
        if isinstance(cls, type):
            return cls()
        return cls

    if isinstance(data, (list, tuple)):
        return (OrderedDict([(envelope, [marshal(d, fields) for d in data])])
                if envelope else [marshal(d, fields) for d in data])

    items = ((k, marshal(data, v) if isinstance(v, dict)
              else make(v).output(k, data))
             for k, v in fields.items())
    return OrderedDict([(envelope, OrderedDict(items))]) if envelope else OrderedDict(items)


